function onCodeSearch(){const value=norm($('#code-search').value).trim();const direct={'iam':'10','iamcest':'10','infarto':'10','iaas':'15','infecciones':'15','hta':'07','hipertension':'07','tension':'07','presion arterial':'07','dm2':'06','diabetes':'06','erc':'08'};codeTopic=direct[value]||'all';renderCodes();}
function fichaCodes(item){const entries=codeEntries.filter(e=>e.itemId===item.id);return `<section class="detail-section ficha-codes"><h3>Códigos CIE-10 y función en la ficha</h3>${item.cie10Note?`<aside class="code-clarification"><strong>Cómo usar los códigos de esta ficha</strong><p>${esc(item.cie10Note)}</p><p class="small-text">${esc(item.cie10NoteSource||'')}</p><a class="source-link" href="${esc(item.sourceFile)}#page=2" target="_blank" rel="noopener">Comprobar en la ficha oficial · páginas 1 y 2 ${svg('file')}</a></aside>`:''}${entries.length?entries.map(e=>codeEntry(e,false)).join(''):'<p>El documento fuente no enumera un código CIE-10 específico para este indicador. Esto no significa que el diagnóstico no se utilice: algunas fichas trabajan con grupos de diagnósticos u otros datos. Revise el apartado «Qué debe quedar registrado para evaluar este indicador».</p>'}<p class="small-text">El diagnóstico registrado debe corresponder a la valoración clínica. El código identifica su función en la ficha; los demás datos necesarios se indican en el apartado de registro.</p><button class="text-link" data-code-topic="${esc(item.categoryId)}">Ver CIE-10 de esta familia ${svg('arrow')}</button></section>`;}
function sourceLinks(item){const sourceLabel=item.sourcePage>1?`Diseño general EPSS · páginas ${item.sourcePage}${item.sourceEndPage?' a '+item.sourceEndPage:''}`:`Comprobar en la ficha original · ${item.sourcePages} ${item.sourcePages===1?'página':'páginas'}`;return `<a class="source-link" href="${sourceUrl(item)}" target="_blank" rel="noopener">${svg('file')}${esc(sourceLabel)}</a>`+(item.supportingSources||[]).map(id=>{const d=docById.get(id);return d?`<a class="source-link" href="${d.file}" target="_blank" rel="noopener">${svg('file')}${esc(d.title)}</a>`:'';}).join('');}
function recordingRequirements(item){const values=Array.isArray(item.recording)?item.recording:item.recording?[item.recording]:[],edusTiming=item.categoryId==='10'||item.id==='12-01-1.0';return values.length?`<section class="detail-section recording-requirements" aria-labelledby="recording-requirements-title"><div class="eyebrow">DATOS PARA LA EVALUACIÓN</div><h3 id="recording-requirements-title">Qué debe quedar registrado para evaluar este indicador</h3><p class="recording-explanation">Los datos pueden ser diagnósticos CIE-10, fechas, horas, resultados, procedimientos o datos administrativos.</p>${edusTiming?'<aside class="edus-timing-note"><strong>Hora del registro y hora de la acción</strong><p>La hora en que se registra una acción puede ser distinta de la hora en que ocurrió. Si se documenta después de aplicar un medicamento, la marca automática de registro no demuestra por sí sola la hora de aplicación ni la llegada física del paciente. Documente oportunamente la acción y compruebe qué dato utiliza el reporte oficial para calcular el indicador.</p></aside>':''}<ul>${values.map(value=>`<li>${esc(asText(value))}</li>`).join('')}</ul></section>`:'';}
function quickSummary(item){return `<section class="quick-summary detail-section"><div class="eyebrow">RESUMEN DE LA FICHA PUBLICADA</div><h3>${item.kind==='evaluation'?'Lo indispensable para cumplir':'Qué aporta y cómo se mide'}</h3><p class="quick-population"><b>A quién aplica</b>${esc(item.population)}</p>${listBlock('Qué debe hacerse',item.requiredActions,'quick-actions')}${listBlock('En qué plazo',item.timing)}${item.successCriterion?`<div class="success-criterion">${svg('check')}<div><b>Criterio de cumplimiento</b><p>${esc(item.successCriterion)}</p></div></div>`:''}${listBlock('No omitir',item.pitfalls,'quick-pitfalls')}${item.calculation||item.formula?`<div class="quick-calculation"><h4>Cómo se cuenta</h4><p>${esc(asText(item.calculation||item.formula))}</p></div>`:''}${tableBlock('Intervenciones acumulativas según edad al corte',item.packageTable)}${tableBlock('Valores de referencia de la ficha',item.riskTable)}${listBlock('Precisiones de la fuente',item.essentialNotes,'quick-precisions')}<div class="quick-meta"><span>${item.kind==='evaluation'?'Meta de la ficha publicada':'Referencia o meta declarada'}</span><strong>${esc(asText(item.target||'No se establece una meta numérica.'))}</strong><small>La meta institucional es distinta del criterio de cumplimiento de cada caso.</small></div>${sourceLinks(item)}</section>`;}
function applicabilityPanel(item){return `<section class="detail-section hospital-applicability-panel"><h3>Aplicabilidad hospitalaria</h3><p>${esc(hospitalText(item))}</p>${item.serviceTags?.length?`<div class="hospital-service-tags">${item.serviceTags.map(tag=>`<span class="pill">${esc(tag)}</span>`).join('')}</div>`:''}<p class="small-text">Compruebe las condiciones, exclusiones y capacidad resolutiva que especifica la ficha.</p></section>`;}
function relatedPanel(item){let r=[];if(item.kind==='evaluation')r=all.filter(x=>x.kind==='complementary'&&((x.evaluationRefs||[]).some(ref=>ref.slice(0,5)===item.family)||(x.relatedEvaluationCodes||[]).some(ref=>ref.slice(0,5)===item.family)));if(!r.length&&item.kind==='evaluation')r=all.filter(x=>x.kind==='complementary'&&x.categoryId===item.categoryId);if(item.kind==='complementary')r=all.filter(x=>x.kind==='evaluation'&&x.categoryId===item.categoryId);return r.length?`<details class="detail-section related-indicators"><summary>${item.kind==='evaluation'?'Complementarios relacionados':'Indicadores de evaluación del tema'} (${r.length})</summary>${r.map(x=>`<button class="text-link" data-open="${esc(x.id)}">${esc(x.code||'Complementario')} · ${esc(x.title)} ${svg('arrow')}</button>`).join('')}</details>`:'';}
function feedbackHref(item=null){const url=new URL('./',location.href);if(item)url.hash='ficha='+encodeURIComponent(item.id);const title=item?(item.code?item.code+' · ':'')+item.title:'Consulta general';const subject='EPSS a la mano · Hospitales: observación o mejora'+(item?.code?' · '+item.code:'');const body='Ficha o indicador: '+title+'\nEnlace consultado: '+url.href+(item?.sourceLabel?'\nReferencia: '+item.sourceLabel:'')+'\n\nObservación, error detectado o propuesta de mejora:\n\n';return 'mailto:msolanoc@ccss.sa.cr?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);}
function openFicha(id,opt={}){
 const item=resolveItem(id);if(!item){toast('No se encontró esa ficha.');return;}const panel=$('#detail-modal .detail-panel');panel.style.setProperty('--topic',COLOR[item.categoryId]||'#536875');panel.style.setProperty('--topic-tint',TINT[item.categoryId]||'#DFE6EB');panel.dataset.family=item.categoryId;lastFocus=document.activeElement;activeId=item.id;detailMode='resumen';recent=[item.id,...recent.filter(v=>v!==item.id)].slice(0,8);persist();renderFavorites();$('#detail-category').textContent=`${item.category} · Hospitales`;$('#detail-category').classList.add('detail-family');$('#detail-category').style.setProperty('--topic',COLOR[item.categoryId]);$('#detail-category').style.setProperty('--topic-tint',TINT[item.categoryId]);
 const changes=(item.changes||[]).map(asText);
 $('#detail-body').innerHTML=`<div class="detail-badges"><span class="pill">${item.kind==='evaluation'?'Indicador de evaluación':'Complementario de apoyo'}</span>${statusPill(item)}</div><div class="detail-code">${esc(item.code||'COMPLEMENTARIO')}</div><div class="ficha-initiative"><b>Iniciativa de la DRIPSSHA</b><span>Dirección de Red Integrada de Prestación de Servicios de Salud Huetar Atlántica</span></div><h2 class="detail-title" id="detail-title">${esc(item.title)}</h2><p class="source-meta">${esc(item.sourceLabel)} · ${esc((item.levels||[]).join(' / '))}<br>Consulte la versión documental y su aplicación en el período evaluado.</p>${applicabilityPanel(item)}${listBlock('Precisiones del documento fuente',item.fullSourceNotes,'source-scope-notes')}<div class="detail-actions"><button class="btn ghost" data-favorite="${esc(item.id)}" aria-pressed="${favorites.has(item.id)}">${svg('star')}${favorites.has(item.id)?'Guardada':'Guardar ficha'}</button><button class="icon-btn" data-copy="${esc(item.id)}" aria-label="Copiar enlace">${svg('copy')}</button><button class="icon-btn" data-print aria-label="Imprimir o compartir PDF original">${svg('print')}</button><a class="btn primary" href="${sourceUrl(item)}" target="_blank" rel="noopener" data-pdf="${esc(item.id)}">${item.sourcePage>1?'PDF fuente':'PDF original'} ${svg('arrow')}</a></div><p class="feedback-inline"><a data-feedback href="${esc(feedbackHref(item))}">Reportar un error o proponer una mejora de esta ficha</a><span>msolanoc@ccss.sa.cr</span></p>${recordingRequirements(item)}<div class="detail-mode-switch reading-switch" role="group" aria-label="Versión de consulta"><button data-detail-mode="resumen" class="active" aria-pressed="true"><b>Resumen</b><span>Requisitos de consulta</span></button><button data-detail-mode="full" aria-pressed="false"><b>Completa (Full)</b><span>Lectura completa</span></button></div>${changes.length?`<div class="integrated-changes"><b>${svg('refresh')} Modificaciones incorporadas</b><ul>${changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></div>`:''}<div id="detail-summary">${quickSummary(item)}</div><div id="detail-full" class="full-criteria hidden"><section class="detail-section"><h3>Ficha completa · ${esc(item.code||'complementaria')}</h3><p>Contenido íntegro de la ficha, organizado para leer en pantalla. El documento fuente conserva la presentación original.</p>${sourceLinks(item)}${renderFullDocument(item.fullText,{metadata:item.fullMetadata,sourceFile:item.sourceFile,pages:item.fullReadingPages})}</section>${item.legacyReference?`<details class="original-text"><summary>${esc(item.legacyReference.title)} · ${esc(item.legacyReference.code)}</summary><p>${esc(item.legacyReference.note)}</p><a class="source-link" href="${item.legacyReference.file}#page=${item.legacyReference.page}" target="_blank" rel="noopener">Abrir referencia anterior</a><pre>${esc(item.legacyReference.fullText)}</pre></details>`:''}</div>${fichaCodes(item)}${relatedPanel(item)}<p class="detail-footnote">Fichas técnicas EPSS 2024-2028. Para indicaciones asistenciales, consulte el protocolo clínico aplicable. <button class="text-link" data-view="fuentes">Fuentes y créditos</button></p>`;
 $('#detail-modal').classList.remove('hidden');document.body.classList.add('modal-open');$('#detail-modal .detail-panel').scrollTop=0;$('#close-detail').focus();if(!opt.noHash)history.replaceState(null,'',`#ficha=${encodeURIComponent(item.id)}`);analyticsPage();track('open_indicator',{indicator:item.code||item.id,kind:item.kind});
}
function setDetailMode(mode){detailMode=mode==='full'?'full':'resumen';$('#detail-summary').classList.toggle('hidden',detailMode==='full');$('#detail-full').classList.toggle('hidden',detailMode!=='full');$$('[data-detail-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.detailMode===detailMode);b.setAttribute('aria-pressed',String(b.dataset.detailMode===detailMode));});$('#detail-'+(detailMode==='full'?'full':'summary')).scrollIntoView({block:'start',behavior:'instant'});track('read_mode',{indicator:activeId,mode:detailMode});}
function closeDetail(noHash=false){$('#detail-modal').classList.add('hidden');document.body.classList.remove('modal-open');activeId=null;if(!noHash){history.replaceState(null,'','#'+activeView);analyticsPage();}if(lastFocus?.isConnected)lastFocus.focus();}
function setView(view,opt={}){if(view==='explorar')view='evaluacion';if(!['evaluacion','complementarios','codigos','favoritas','cambios','fuentes'].includes(view))view='evaluacion';if(activeId)closeDetail(true);activeView=view;$$('.view').forEach(el=>el.classList.toggle('hidden',el.id!==('view-'+(isCatalog()?'explorar':view))));$$('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);if(el.closest('nav'))el.setAttribute('aria-current',el.dataset.view===view?'page':'false');});if(!opt.noHash)history.replaceState(null,'','#'+view);if(isCatalog())renderCatalog();if(view==='favoritas')renderFavorites();if(view==='codigos')renderCodes();if(!opt.noScroll)window.scrollTo({top:0,behavior:'instant'});if(!opt.noAnalytics){analyticsPage();track('section_view',{section:view});}}
function useHash(){const h=decodeURIComponent(location.hash.slice(1));if(h==='mr'){setView('evaluacion');return;}if(h.startsWith('ficha=')){setView('evaluacion',{noHash:true,noScroll:true,noAnalytics:true});openFicha(h.slice(6),{noHash:true});}else setView(h||'evaluacion',{noHash:true});}
function renderChanges(){$('#updates').innerHTML=all.filter(x=>x.changes?.length).map(x=>`<article class="update-card"><div class="update-meta"><span class="pill">${esc(x.code||'Complementario')}</span><span>Incorporado en ambas vistas</span></div><h2>${esc(x.title)}</h2><ul>${x.changes.map(c=>`<li>${esc(asText(c))}</li>`).join('')}</ul><button class="text-link" data-open="${esc(x.id)}">Abrir ficha actual ${svg('arrow')}</button><a class="source-link" href="${sourceUrl(x)}" target="_blank" rel="noopener">Ver documento fuente</a></article>`).join('')||'<div class="empty-state"><h2>Sin modificaciones comparadas en esta edición</h2><p>Cada ficha conserva el código y la versión del documento incorporado.</p></div>';$('#interpretation-notes').innerHTML='<article class="source-card"><h3>La fecha de descarga no es una fecha de vigencia</h3><p>Las fichas conservan sus códigos y versiones. La recopilación no afirma haber reunido todos los oficios institucionales posteriores.</p></article><article class="source-card"><h3>El ámbito forma parte del indicador</h3><p>Una ficha hospitalaria puede corresponder a un nivel, servicio o grupo de hospitales concreto. La clasificación se consulta dentro de cada ficha.</p></article>';}
function renderSources(){
 $('#source-documents').innerHTML=documents.filter(d=>d.role!=='ficha').map(d=>`<article class="source-card"><span class="source-badge ${d.role==='base'?'':'accent'}">${esc({'base':'BASE DOCUMENTAL','informe':'INFORME','resumen_regional':'ANTECEDENTE REGIONAL','lineamiento':'LINEAMIENTO','referencia':'DOCUMENTO DE APOYO'}[d.role]||'FUENTE')}</span><h2>${esc(d.title)}</h2>${d.showOriginalName===false?'':`<p class="source-original-name">${esc(d.originalName)}</p>`}${d.referenceNote?`<p class="reference-note">${esc(d.referenceNote)}</p>`:''}<p>${d.pages} páginas · PDF original.</p><a class="btn ghost" href="${d.file}" target="_blank" rel="noopener">Abrir documento ${svg('arrow')}</a></article>`).join('');
 $('#source-notes').innerHTML=`<article class="source-card source-wide"><h2>Inventario de fichas de esta edición</h2><p>${all.filter(x=>x.kind==='evaluation').length} indicadores de evaluación y ${all.filter(x=>x.kind==='complementary').length} complementarios con aplicabilidad hospitalaria documentada.</p><details><summary>Ver los PDF de las fichas (${documents.filter(d=>d.role==='ficha').length})</summary><div class="document-inventory">${documents.filter(d=>d.role==='ficha').map(d=>`<a href="${d.file}" target="_blank" rel="noopener">${esc(d.originalName)} ${svg('file')}</a>`).join('')}</div></details></article><article class="source-card source-wide"><h2>Uso de estadísticas</h2><p id="analytics-status">La medición de uso se habilitará con una configuración propia para la aplicación hospitalaria.</p></article>`;
}
function selectInstallDevice(device){const selected=['android','computer'].includes(device)?device:'iphone';$$('[data-install-device]').forEach(b=>{b.classList.toggle('active',b.dataset.installDevice===selected);b.setAttribute('aria-pressed',String(b.dataset.installDevice===selected));});$$('[data-install-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.installPanel!==selected));}
function installHelp(){installLastFocus=document.activeElement;selectInstallDevice(/Android/i.test(navigator.userAgent)?'android':/iPhone|iPad|iPod/i.test(navigator.userAgent)?'iphone':'computer');$('#install-modal').classList.remove('hidden');document.body.classList.add('modal-open');$('#install-modal .detail-panel').scrollTop=0;$('#close-install').focus();}
function closeInstall(){$('#install-modal').classList.add('hidden');document.body.classList.remove('modal-open');(installLastFocus?.isConnected?installLastFocus:$('#install-btn')).focus();}
async function offline(){if(!('serviceWorker'in navigator)){$('#offline-btn').disabled=true;$('#offline-status').textContent='Este navegador no permite guardar la app sin conexión.';return;}try{const reg=await navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});reg.update().catch(()=>{});}catch{$('#offline-status').textContent='No se pudo activar el guardado sin conexión en esta sesión.';}}
async function cacheDocuments(){const btn=$('#offline-btn');btn.disabled=true;$('#offline-status').textContent='Guardando fichas y documentos. Mantenga abierta esta página…';try{const reg=await navigator.serviceWorker.ready,channel=new MessageChannel(),done=new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('El guardado no finalizó a tiempo.')),180000);channel.port1.onmessage=e=>{if(e.data.stage==='viewer'){$('#offline-status').textContent='Preparando el visor de PDF para usarlo sin conexión…';return;}if(e.data.progress){$('#offline-status').textContent=`Guardando documentos: ${e.data.progress} de ${e.data.total}…`;return;}clearTimeout(timer);e.data.ok?resolve(e.data):reject(Error(e.data.error));};});reg.active.postMessage({type:'CACHE_DOCUMENTS',files:documents.map(d=>d.file)},[channel.port2]);const r=await done;$('#offline-status').textContent=`${r.count} documentos guardados en este dispositivo.`;}catch(e){$('#offline-status').textContent=e.message||'No se pudieron guardar todos los documentos.';}finally{btn.disabled=false;}}
async function analytics(){try{
 if(analyticsMeasurementId)return;
 const c=await fetch('assets/config.json').then(r=>r.json());if(!/^G-[A-Z0-9]+$/.test(c.analyticsMeasurementId||''))return;
 analyticsMeasurementId=c.analyticsMeasurementId;
 window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments);};
 window.gtag('js',new Date());window.gtag('config',analyticsMeasurementId,{send_page_view:false,allow_google_signals:false,allow_ad_personalization_signals:false,...analyticsContext()});
 analyticsReady=true;analyticsPage();track('section_view',{section:activeView});
 const item=all.find(x=>x.id===activeId);if(item)track('open_indicator',{indicator:item.code||item.id,kind:item.kind});
 const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(analyticsMeasurementId);
 s.addEventListener('error',()=>{analyticsReady=false;const status=$('#analytics-status');if(status)status.textContent='Google Analytics está configurado, pero la etiqueta no pudo cargarse en esta sesión.';});document.head.append(s);
 $('#analytics-status').textContent='Google Analytics configurado para esta aplicación. Se miden visitas, secciones, consultas por indicador y modo de lectura; no se envía el texto de las búsquedas.';
}catch{}}
document.addEventListener('epss:document-open',e=>{track('open_source',{indicator:e.detail?.indicator||activeId||'documento'});if(e.detail?.printMode)track('print_source',{indicator:e.detail?.indicator||activeId||'documento'});});
document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a,[data-id]');if(!el)return;
 if(el.hasAttribute('data-feedback')){el.href=feedbackHref(activeId?resolveItem(activeId):null);return;}
 if(el.dataset.installDevice){selectInstallDevice(el.dataset.installDevice);return;}
 if(el.hasAttribute('data-copy-app-link')){const link=new URL('./',location.href).href;try{await navigator.clipboard.writeText(link);toast('Enlace copiado. Ábralo en Safari o Chrome.');}catch{toast('Enlace de la app: '+link);}return;}
 if(el.dataset.favorite){toggleFavorite(el.dataset.favorite);return;}
 if(el.dataset.copyCode){try{await navigator.clipboard.writeText(el.dataset.copyCode);toast('Código '+el.dataset.copyCode+' copiado.');}catch{toast('Código: '+el.dataset.copyCode);}track('copy_cie10',{code:el.dataset.copyCode});return;}
 if(el.dataset.codeTopic){chooseCodeTopic(el.dataset.codeTopic);return;}
 if(el.hasAttribute('data-code-clear')){clearCodeSearch();return;}
 if(el.dataset.view){setView(el.dataset.view);return;}
 if(el.dataset.topic){activeTopic=el.dataset.topic;if(!isCatalog())setView('evaluacion');else renderCatalog();return;}
 if(el.dataset.open){openFicha(el.dataset.open);return;}
 if(el.dataset.search){activeTopic='all';$('#search').value=el.dataset.search;setView('evaluacion');$('#search').focus();return;}
 if(el.dataset.detailMode){setDetailMode(el.dataset.detailMode);return;}
 if(el.hasAttribute('data-reset')){activeTopic='all';activeHospital='all';$('#hospital-filter').value='all';$('#search').value='';renderCatalog();return;}
 if(el.dataset.copy){const u=new URL(location.href);u.hash='ficha='+encodeURIComponent(el.dataset.copy);try{await navigator.clipboard.writeText(u.href);toast('Enlace de ficha copiado.');}catch{toast('Copie la dirección de esta ficha desde el navegador.');}return;}
 if(el.dataset.pdf){track('open_source',{indicator:el.dataset.pdf});return;}
 if(el.dataset.id&&!e.target.closest('button,a'))openFicha(el.dataset.id);
});
$('#hospital-filter').addEventListener('change',()=>{activeHospital=$('#hospital-filter').value;renderCatalog();});$('#search').addEventListener('input',renderCatalog);$('#sort-filter').addEventListener('change',renderCatalog);$('#code-search').addEventListener('input',onCodeSearch);$('#close-detail').addEventListener('click',()=>closeDetail());$('#detail-modal').addEventListener('click',e=>{if(e.target.id==='detail-modal')closeDetail();});$('#install-btn').addEventListener('click',installHelp);$('#close-install').addEventListener('click',closeInstall);$('#install-modal').addEventListener('click',e=>{if(e.target.id==='install-modal')closeInstall();});$('#offline-btn').addEventListener('click',cacheDocuments);
window.addEventListener('hashchange',useHash);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#native-install').classList.remove('hidden');});$('#native-install').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;closeInstall();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#install-modal').classList.contains('hidden'))closeInstall();else if(activeId)closeDetail();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-id]')){e.preventDefault();openFicha(e.target.dataset.id);}if(e.key==='/'&&!e.target.matches('input,textarea,select')&&!activeId){e.preventDefault();if(!isCatalog())setView('evaluacion');$('#search').focus();}if(e.key==='Tab'&&document.body.classList.contains('modal-open')){const modal=!$('#install-modal').classList.contains('hidden')?$('#install-modal'):$('#detail-modal'),n=[...modal.querySelectorAll('button,a,input,select,[tabindex="0"]')].filter(el=>el.getClientRects().length&&!el.disabled);if(!n.length)return;if(e.shiftKey&&document.activeElement===n[0]){e.preventDefault();n.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===n.at(-1)){e.preventDefault();n[0].focus();}}});
async function init(){fillIcons();try{const response=await fetch('assets/catalogo.json',{cache:'no-cache'});if(!response.ok)throw Error('No se pudo cargar el catálogo.');const c=await response.json();all=c.items;categories=c.categories;documents=c.documents;docById=new Map(documents.map(d=>[d.id,d]));favorites=new Set([...favorites].map(resolveItem).filter(Boolean).map(x=>x.id));recent=recent.map(resolveItem).filter(Boolean).map(x=>x.id);codeEntries=all.flatMap(item=>(item.cie10||[]).map(e=>({...e,itemId:item.id,itemCode:item.code||'',itemTitle:item.title,categoryId:item.categoryId})));$('#count-evaluation').textContent=all.filter(x=>x.kind==='evaluation').length;$('#count-complementary').textContent=all.filter(x=>x.kind==='complementary').length;$('#total-side').textContent=all.filter(x=>x.kind==='evaluation').length;renderTopics();renderFavorites();renderCodes();renderChanges();renderSources();useHash();offline();analytics();}catch(e){$('#cards').innerHTML=`<div class="empty-state"><h2>No se pudo abrir el catálogo</h2><p>${esc(e.message)} Vuelva a cargar la página.</p></div>`;$('#catalog-status').innerHTML=`${svg('info')}<div>El contenido no está disponible en esta sesión. Vuelva a cargar la app.</div>`;}}
init();
